/* Keeps Rust std/core internals out of libobs's dynamic symbol table, so
 * ENABLE_RUST_LIBOBS=ON exports exactly what the C build exports. The C ABI
 * shims are #[no_mangle] and stay global. libobs exports no C++ symbols. */
{
  local:
    ep_free;
    add_alignment;
    obs_bounds_place;
    _ZN*;
    _R*;
    rust_eh_personality;
    /* Rust state for base.c. The variadic entry points stay in
     * util/base-variadic.c and keep the public names blog/blogva/bcrash. */
    base_begin_crash;
    base_default_log_handler;
    /* profiler.c's variadic profile_store_name stays in
     * util/profiler-variadic.c and pushes through this. */
    profiler_name_store_push;
    /* profiler-io.c: non-static, not EXPORT. */
    profile_print_func;
    base_log_literal;
    /* utf8.c is not exported by the C libobs, so its Rust shims are hidden
     * too (listed in rust-hidden.txt). */
    utf8_to_wchar;
    wchar_to_utf8;
    /* platform-nix-dbus.c: no EXPORT; called within libobs only. */
    dbus_sleep_info_create;
    dbus_inhibit_sleep;
    dbus_sleep_info_destroy;
    /* platform-nix-portal.c: no EXPORT; called within libobs only. */
    portal_inhibit_info_create;
    portal_inhibit;
    portal_inhibit_info_destroy;
    /* platform-nix.c. obs-module.c calls it; the C build does not export it. */
    get_plugin_info;
    /* obs-hotkey-name-map.c. Declared in obs-internal.h; obs.c calls it on
     * shutdown. Not EXPORT. */
    obs_hotkey_name_map_free;
    /* obs-hotkey-bindings.c. obs-hotkey.c calls them inside libobs. Not
     * EXPORT. */
    obs_hotkey_combination_from_data;
    obs_hotkey_combination_bindable;
    obs_hotkey_combination_to_data;
    /* obs-hotkey-press.c. obs-hotkey.c calls them inside libobs. Not
     * EXPORT. */
    obs_hotkey_binding_query;
    obs_hotkey_binding_inject;
    obs_hotkeys_query_modifiers;
    /* obs-hotkey-pair.c. obs-hotkey.c registers them as the callbacks of a
     * pair's hotkeys. Not EXPORT. */
    obs_hotkey_pair_first_func;
    obs_hotkey_pair_second_func;
    /* platform-windows.c. Not EXPORT. */
    get_win_release_id;
    DllMain;
    /* video-io.c. Not EXPORT; callers are inside libobs. */
    video_output_inc_texture_encoders;
    video_output_dec_texture_encoders;
    video_output_inc_texture_frames;
    video_output_inc_texture_skipped_frames;
    video_output_create_with_frame_rate_divisor;
    video_output_free_frame_rate_divisor;
    /* obs-data.c: json_decref is a static inline. The glue is not EXPORT. */
    obs_data_json_decref;
    /* obs-scene-bounds.c. obs-scene.c calls it inside libobs. Not EXPORT. */
    obs_bounds_fit_scale;
    /* obs-scene-blend.c: the blend mode table, data. obs-scene.c reads it
     * inside libobs. Not EXPORT. */
    obs_blend_mode_params;
    /* obs-scene-coords.c. obs-scene.c calls them inside libobs. Not
     * EXPORT. */
    obs_scene_coords_nudge;
    obs_scene_coords_keep_scale;
    obs_scene_nudge_abs;
    obs_scene_pos_to_absolute;
    obs_scene_pos_from_absolute;
    obs_scene_size_to_absolute;
    obs_scene_size_from_absolute;
    obs_scene_item_canvas_scale;
    obs_scene_item_relative_scale;
    /* obs-scene-group-transform.c. obs-scene.c calls them inside libobs.
     * Not EXPORT. */
    obs_scene_transform_val;
    obs_scene_group_transform;
    /* obs-scene-audio-actions.c. obs-scene-item-audio-actions.c calls them
     * inside libobs. Not EXPORT. */
    obs_scene_audio_actions_apply;
    obs_scene_audio_action_due;
    /* obs-output-caption-text.c. obs-output.c calls it inside libobs. Not
     * EXPORT. */
    obs_output_caption_text_page;
    /* obs-output-protocols.c. obs-output.c calls it inside libobs. Not
     * EXPORT. */
    obs_output_protocol_list_count;
    /* obs-output-delay.c. obs-output.c calls them inside libobs. Not
     * EXPORT. */
    process_delay;
    obs_output_delay_start;
    obs_output_delay_stop;
    obs_output_cleanup_delay;
    /* obs-output-interleave.c. obs-output.c calls them inside libobs. Not
     * EXPORT. */
    interleave_packets;
    get_encoder_index;
    free_packets;
    /* pulseaudio-stream-flags.c. pulseaudio-output.c calls them inside
     * libobs. Not EXPORT. */
    pulseaudio_monitor_stream_flags;
    pulseaudio_monitor_reset_on_sink_event;
    pulseaudio_monitor_backlog_excess;
    /* pulseaudio-monitor-format.c. pulseaudio-output.c and
     * pulseaudio-wrapper.c call them inside libobs. Not EXPORT. */
    pulseaudio_channels_to_obs_speakers;
    pulseaudio_to_obs_audio_format;
    pulseaudio_channel_map;
    pulseaudio_monitor_sink_format;
    pulseaudio_monitor_sink_channels;
    pulseaudio_monitor_process_volume;
    pulseaudio_monitor_queued_bytes;
    pulseaudio_monitor_drop_split;
    pulseaudio_monitor_devices_match;
    /* obs-nix-hotkey-state.c. obs-nix-wayland.c and obs-nix-portal-shortcuts.c
     * call them inside libobs. Not EXPORT. */
    obs_nix_hotkey_state_free;
    obs_nix_hotkey_state_set_key;
    obs_nix_hotkey_state_set_modifiers;
    obs_nix_hotkey_state_clear_keys;
    obs_nix_hotkey_state_set_shortcut;
    obs_nix_hotkey_state_flush;
    obs_nix_hotkey_state_is_pressed;
    /* obs-nix-portal-shortcut-ids.c. obs-nix-portal-shortcuts.c calls them
     * inside libobs. Not EXPORT. */
    obs_nix_portal_shortcut_id;
    obs_nix_portal_shortcut_combo;
    obs_nix_portal_shortcut_trigger;
    /* obs-nix-portal-shortcut-sets.c. obs-nix-portal-shortcuts.c calls them
     * inside libobs. Not EXPORT. */
    obs_nix_portal_sets_has;
    obs_nix_portal_sets_unchanged;
    obs_nix_portal_sets_request;
    obs_nix_portal_sets_partition;
    /* obs-context-names.c. obs.c calls them inside libobs. Not EXPORT. */
    obs_context_name_dup;
    obs_context_name_deduplicate;
    /* obs-video-plan.c. obs.c calls them inside libobs. Not EXPORT. */
    obs_video_size_valid;
    obs_video_align_output_size;
    obs_video_output_size_valid;
    obs_video_scale_type_name;
    obs_video_output_plan;
};
